#include <string>
#include <vector>

TEST("slots run in order with the arguments") {
  Signal<int, std::string> s;
  std::vector<std::string> log;
  s.connect([&](int n, const std::string& w) { log.push_back("a" + std::to_string(n) + w); });
  s.connect([&](int n, std::string w) { log.push_back("b" + std::to_string(n) + w); });
  CHECK_EQ(s.emit(1, "x"), std::size_t{2});
  CHECK(log == (std::vector<std::string>{"a1x", "b1x"}));
}

TEST("every slot receives the same value (no move-from)") {
  Signal<std::string> s;
  std::vector<std::string> got;
  for (int i = 0; i < 3; ++i) s.connect([&](std::string v) { got.push_back(std::move(v)); });
  s.emit(std::string("payload"));
  CHECK(got == (std::vector<std::string>{"payload", "payload", "payload"}));
}

TEST("ids are unique and start at 1") {
  Signal<> s;
  auto a = s.connect([] {});
  auto b = s.connect([] {});
  CHECK_EQ(a, std::size_t{1});
  CHECK(a != b);
  CHECK_EQ(s.size(), std::size_t{2});
}

TEST("disconnect removes a slot") {
  Signal<> s;
  int calls = 0;
  auto id = s.connect([&] { ++calls; });
  s.connect([&] { calls += 10; });
  CHECK(s.disconnect(id));
  CHECK(!s.disconnect(id));
  CHECK(!s.disconnect(999));
  CHECK_EQ(s.emit(), std::size_t{1});
  CHECK_EQ(calls, 10);
}

TEST("changes during emit apply to the next emit") {
  Signal<> s;
  std::vector<std::string> log;
  std::size_t second = 0;
  s.connect([&] {
    log.push_back("first");
    s.disconnect(second);                         // removed during emit: still runs this time
    s.connect([&] { log.push_back("late"); });    // added during emit: not called this time
  });
  second = s.connect([&] { log.push_back("second"); });
  s.emit();
  CHECK(log == (std::vector<std::string>{"first", "second"}));
  log.clear();
  s.emit();
  CHECK_EQ(log.front(), std::string("first"));
  CHECK_EQ(log.back(), std::string("late"));
}

TEST("an empty signal emits to nobody") {
  Signal<double> s;
  CHECK_EQ(s.emit(1.5), std::size_t{0});
  CHECK_EQ(s.size(), std::size_t{0});
}

