#include <cstddef>
#include <functional>
#include <utility>
#include <vector>

template <typename... Args>
class Signal {
 public:
  using Slot = std::function<void(Args...)>;

  std::size_t connect(Slot slot) {
    slots_.emplace_back(next_id_, std::move(slot));
    return next_id_++;
  }

  bool disconnect(std::size_t id) {
    for (auto it = slots_.begin(); it != slots_.end(); ++it) {
      if (it->first == id) {
        slots_.erase(it);
        return true;
      }
    }
    return false;
  }

  std::size_t emit(Args... args) {
    auto snapshot = slots_;  // slots may connect/disconnect while we're calling them
    // Pass `args...` as lvalues. std::forward here would move the arguments into
    // the first slot and hand the rest moved-from values.
    for (auto& [id, slot] : snapshot) slot(args...);
    return snapshot.size();
  }

  std::size_t size() const { return slots_.size(); }

 private:
  std::vector<std::pair<std::size_t, Slot>> slots_;
  std::size_t next_id_ = 1;
};
